import { v4 as uuidv4 } from "uuid";

const defaultHeaders = {
  Accept: "*/*",
  "Accept-Encoding": "gzip, deflate, br, zstd",
  "Accept-Language": "en-US,en;q=0.9",
  origin: "https://robinhood.com",
